import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
    const env = loadEnv(mode, '.', '');
    return {
      server: {
        port: 3000,
        host: '0.0.0.0',
      },
      plugins: [react()],
      define: {
        'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
        'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
      },
      resolve: {
        alias: {
          '@': path.resolve(__dirname, '.'),
        }
      }
    };
});

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { PropertyCard } from './components/PropertyCard';
import { AIConcierge } from './components/AIConcierge';
import { MenuDrawer, LoginModal, BookingModal, SearchModal, Toast } from './components/Modals';
import { MOCK_PROPERTIES, MOCK_AGENTS } from './constants';
import { Property, AppView } from './types';
import { ArrowLeft, Star, Check, Instagram, Linkedin, Twitter, ExternalLink, MapPin, Mail, Phone } from 'lucide-react';

const App: React.FC = () => {
  // View State
  const [view, setView] = useState<AppView>(AppView.HOME);
  const [selectedProperty, setSelectedProperty] = useState<Property | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredProperties, setFilteredProperties] = useState<Property[]>(MOCK_PROPERTIES);

  // Modal State
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isLoginOpen, setIsLoginOpen] = useState(false);
  const [isBookingOpen, setIsBookingOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  // User & Interaction State
  const [user, setUser] = useState<{ name: string } | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // --- Handlers ---

  const handleSearch = (query: string) => {
    setSearchQuery(query);
    if (!query.trim()) {
      setFilteredProperties(MOCK_PROPERTIES);
    } else {
      const lowerQ = query.toLowerCase();
      const results = MOCK_PROPERTIES.filter(p => 
        p.title.toLowerCase().includes(lowerQ) ||
        p.location.toLowerCase().includes(lowerQ) ||
        p.category.toLowerCase().includes(lowerQ) ||
        p.description.toLowerCase().includes(lowerQ)
      );
      setFilteredProperties(results);
    }
    setView(AppView.SEARCH_RESULTS);
    window.scrollTo(0, 0);
  };

  const handlePropertyClick = (property: Property) => {
    setSelectedProperty(property);
    setView(AppView.DETAILS);
    window.scrollTo(0, 0);
  };

  const handleGoHome = () => {
    setView(AppView.HOME);
    setSelectedProperty(null);
    setSearchQuery('');
    setFilteredProperties(MOCK_PROPERTIES);
    window.scrollTo(0, 0);
  };

  const handleLogin = (name: string) => {
    setUser({ name });
    setToastMessage(`Welcome back, ${name}.`);
  };

  const handleBookingSubmit = () => {
    setToastMessage("Your viewing request has been sent securely.");
  };

  const handleDownloadBrochure = () => {
    setToastMessage("Brochure downloading... Check your folder.");
  };

  const handleMenuNavigate = (section: string) => {
    setIsMenuOpen(false);
    window.scrollTo(0, 0);

    switch(section) {
      case 'Home':
        handleGoHome();
        break;
      case 'Buy':
        setView(AppView.BUY);
        break;
      case 'Rent':
        setView(AppView.RENT);
        break;
      case 'New Developments':
        setView(AppView.NEW_DEVELOPMENTS);
        break;
      case 'Journal':
        setView(AppView.JOURNAL);
        break;
      case 'Contact':
        setView(AppView.CONTACT);
        break;
      case 'Agents':
        handleGoHome();
        setTimeout(() => {
            document.getElementById('agents-section')?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
        break;
      default:
        setToastMessage(`${section} coming soon.`);
    }
  };

  // --- Sub-Components for Views ---

  const SearchResultsPage = () => (
    <div className="pt-28 px-6 max-w-7xl mx-auto min-h-screen animate-in fade-in slide-in-from-bottom-4">
      <div className="mb-12 border-b border-white/10 pb-8">
        <button onClick={handleGoHome} className="flex items-center gap-2 text-gray-400 hover:text-luxe-sand mb-6 transition-colors">
          <ArrowLeft size={16} /> Back Home
        </button>
        <h1 className="text-4xl md:text-5xl font-serif text-luxe-sand mb-4">
          Search Results
        </h1>
        <p className="text-xl text-gray-300">
          {filteredProperties.length} result{filteredProperties.length !== 1 ? 's' : ''} for <span className="text-white italic">"{searchQuery}"</span>
        </p>
      </div>

      {filteredProperties.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-20">
          {filteredProperties.map(prop => (
            <PropertyCard 
              key={prop.id} 
              property={prop} 
              onClick={handlePropertyClick} 
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-32 bg-white/5 rounded-xl border border-white/10">
           <h3 className="text-2xl font-serif text-gray-400 mb-2">No properties found.</h3>
           <p className="text-gray-500 mb-6">Try adjusting your search criteria.</p>
           <button onClick={() => setIsSearchOpen(true)} className="text-luxe-sand hover:text-white border-b border-luxe-sand pb-1">Search Again</button>
        </div>
      )}
    </div>
  );

  const ListingPage = ({ title, filterType }: { title: string, filterType: 'sale' | 'rent' | 'new' }) => {
    const properties = MOCK_PROPERTIES.filter(p => {
        if (filterType === 'new') return true; // Showing all for demo
        return p.status === filterType;
    });

    return (
        <div className="pt-28 px-6 max-w-7xl mx-auto min-h-screen animate-in fade-in">
            <div className="mb-16 text-center max-w-3xl mx-auto">
                <h1 className="text-5xl md:text-6xl font-serif text-luxe-sand mb-6">{title}</h1>
                <p className="text-gray-400 text-lg font-light leading-relaxed">
                    Curated selections of the world's most exceptional properties. 
                    Each residence in our {title.toLowerCase()} portfolio has been vetted for architectural significance and lifestyle amenities.
                </p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-20">
                {properties.length > 0 ? properties.map(prop => (
                    <PropertyCard key={prop.id} property={prop} onClick={handlePropertyClick} />
                )) : (
                    <div className="col-span-2 text-center py-20 text-gray-500">
                        Additional inventory for this category is available upon private request.
                    </div>
                )}
            </div>
        </div>
    );
  };

  const JournalPage = () => (
      <div className="pt-28 px-6 max-w-7xl mx-auto min-h-screen animate-in fade-in">
          <h1 className="text-5xl md:text-7xl font-serif text-luxe-sand mb-16 text-center">The Journal</h1>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-12 mb-20">
              <div className="group cursor-pointer">
                  <div className="overflow-hidden rounded-sm mb-6">
                      <img src="https://picsum.photos/id/20/800/600" alt="Article" className="w-full h-[400px] object-cover transform group-hover:scale-105 transition-transform duration-700" />
                  </div>
                  <span className="text-sky-teal text-xs uppercase tracking-widest block mb-2">Architecture</span>
                  <h3 className="text-3xl font-serif text-white group-hover:text-luxe-sand transition-colors mb-3">The Return of Brutalism in Coastal Living</h3>
                  <p className="text-gray-400 leading-relaxed">Exploring how raw concrete and organic forms are redefining luxury beach houses in 2025...</p>
              </div>
              <div className="group cursor-pointer">
                  <div className="overflow-hidden rounded-sm mb-6">
                      <img src="https://picsum.photos/id/36/800/600" alt="Article" className="w-full h-[400px] object-cover transform group-hover:scale-105 transition-transform duration-700" />
                  </div>
                  <span className="text-sky-teal text-xs uppercase tracking-widest block mb-2">Market Analysis</span>
                  <h3 className="text-3xl font-serif text-white group-hover:text-luxe-sand transition-colors mb-3">Why Kyoto is the New Aspen</h3>
                  <p className="text-gray-400 leading-relaxed">Global investors are shifting focus to Japan's ancient capital for its stability, culture, and architectural preservation...</p>
              </div>
          </div>
      </div>
  );

  const ContactPage = () => (
      <div className="pt-28 px-6 max-w-7xl mx-auto min-h-screen animate-in fade-in">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
              <div>
                  <h1 className="text-5xl font-serif text-luxe-sand mb-8">Get in Touch</h1>
                  <p className="text-gray-300 text-lg mb-12 font-light">
                      Whether you are looking to acquire a new residence or maximize the value of your current portfolio, our private office is at your disposal.
                  </p>

                  <div className="space-y-8">
                      <div className="flex items-start gap-4">
                          <MapPin className="text-sky-teal mt-1" />
                          <div>
                              <h4 className="text-white font-serif text-lg">Global Headquarters</h4>
                              <p className="text-gray-400 text-sm mt-1">10 Hudson Yards, Floor 45<br/>New York, NY 10001</p>
                          </div>
                      </div>
                      <div className="flex items-start gap-4">
                          <Phone className="text-sky-teal mt-1" />
                          <div>
                              <h4 className="text-white font-serif text-lg">Private Office</h4>
                              <p className="text-gray-400 text-sm mt-1">+1 (212) 555-0199</p>
                          </div>
                      </div>
                      <div className="flex items-start gap-4">
                          <Mail className="text-sky-teal mt-1" />
                          <div>
                              <h4 className="text-white font-serif text-lg">Inquiries</h4>
                              <p className="text-gray-400 text-sm mt-1">concierge@nexora.realty</p>
                          </div>
                      </div>
                  </div>
              </div>

              <div className="bg-white/5 p-10 rounded-xl border border-white/10">
                  <h3 className="text-2xl font-serif text-white mb-6">Send a Message</h3>
                  <form className="space-y-6" onSubmit={(e) => { e.preventDefault(); setToastMessage("Message sent. We will respond shortly."); }}>
                      <div className="grid grid-cols-2 gap-6">
                          <div className="space-y-2">
                              <label className="text-xs text-gray-500 uppercase">First Name</label>
                              <input type="text" className="w-full bg-black/40 border border-white/10 p-3 text-white rounded focus:border-sky-teal/50 focus:outline-none" />
                          </div>
                          <div className="space-y-2">
                              <label className="text-xs text-gray-500 uppercase">Last Name</label>
                              <input type="text" className="w-full bg-black/40 border border-white/10 p-3 text-white rounded focus:border-sky-teal/50 focus:outline-none" />
                          </div>
                      </div>
                      <div className="space-y-2">
                          <label className="text-xs text-gray-500 uppercase">Email</label>
                          <input type="email" className="w-full bg-black/40 border border-white/10 p-3 text-white rounded focus:border-sky-teal/50 focus:outline-none" />
                      </div>
                      <div className="space-y-2">
                          <label className="text-xs text-gray-500 uppercase">Message</label>
                          <textarea className="w-full bg-black/40 border border-white/10 p-3 text-white rounded focus:border-sky-teal/50 focus:outline-none h-32 resize-none" />
                      </div>
                      <button type="submit" className="w-full bg-luxe-sand text-onyx py-4 font-medium hover:bg-white transition-colors uppercase tracking-widest text-sm">
                          SendMessage
                      </button>
                  </form>
              </div>
          </div>
      </div>
  );

  return (
    <div className="min-h-screen bg-onyx text-white selection:bg-sky-teal selection:text-onyx font-sans">
      <Navbar 
        onGoHome={handleGoHome} 
        onMenuClick={() => setIsMenuOpen(true)}
        onSearchClick={() => setIsSearchOpen(true)}
        onLoginClick={() => setIsLoginOpen(true)}
        user={user}
        onLogout={() => { setUser(null); setToastMessage("Logged out successfully."); }}
      />

      <main>
        {view === AppView.HOME && (
            <>
            <Hero onSearch={handleSearch} />
            <section className="py-24 px-6 max-w-7xl mx-auto">
                <div className="flex justify-between items-end mb-16">
                <div>
                    <h2 className="text-4xl font-serif text-luxe-sand mb-2">Curated Residences</h2>
                    <p className="text-gray-400 font-light">Handpicked for the discerning few.</p>
                </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {MOCK_PROPERTIES.slice(0, 4).map(prop => (
                    <PropertyCard 
                        key={prop.id} 
                        property={prop} 
                        onClick={handlePropertyClick} 
                    />
                ))}
                </div>
            </section>

            <section id="agents-section" className="bg-white/5 py-24">
                <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
                <div className="relative">
                    <div className="absolute -top-10 -left-10 w-full h-full border border-luxe-sand/20 z-0 hidden md:block"></div>
                    <img src="https://picsum.photos/id/101/800/1000" alt="Lifestyle" className="relative z-10 w-full h-[600px] object-cover grayscale hover:grayscale-0 transition-all duration-700" />
                </div>

                <div>
                    <h2 className="text-4xl md:text-5xl font-serif text-luxe-sand mb-8 leading-tight">
                    Expertise Beyond <br/> The Transaction.
                    </h2>
                    <p className="text-gray-300 mb-10 leading-relaxed font-light text-lg">
                    Nexora agents are not just brokers; they are curators of lifestyle. With deep roots in architecture, design, and global finance, we ensure your next acquisition is a masterpiece.
                    </p>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    {MOCK_AGENTS.map(agent => (
                        <div 
                            key={agent.id} 
                            className="p-6 glass-panel hover:bg-white/5 transition-colors cursor-pointer group"
                            onClick={() => setToastMessage(`Contacting ${agent.name}...`)}
                        >
                            <div className="flex items-center gap-4 mb-4">
                            <img src={agent.imageUrl} alt={agent.name} className="w-12 h-12 rounded-full object-cover" />
                            <div>
                                <h4 className="font-serif text-white group-hover:text-luxe-sand">{agent.name}</h4>
                                <p className="text-xs text-gray-500 uppercase">{agent.title}</p>
                            </div>
                            </div>
                            <div className="flex gap-4 text-gray-400">
                            <Instagram size={16} className="hover:text-rose-gold" />
                            <Linkedin size={16} className="hover:text-rose-gold" />
                            </div>
                        </div>
                    ))}
                    </div>
                </div>
                </div>
            </section>

            <section className="py-32 max-w-4xl mx-auto px-6 text-center">
                <div className="mb-8 flex justify-center gap-1 text-luxe-sand">
                {[1,2,3,4,5].map(i => <Star key={i} size={14} fill="#E9DCC3" stroke="none" />)}
                </div>
                <blockquote className="text-3xl md:text-5xl font-serif leading-snug text-white mb-10">
                "Nexora redefined our expectations. The AI integration wasn't just a gimmick; it found us a property that wasn't even on our radar, but felt like home the moment we walked in."
                </blockquote>
                <cite className="not-italic">
                <span className="block text-luxe-sand font-sans font-bold tracking-wider uppercase text-sm">Julian & Sarah Vance</span>
                <span className="block text-gray-500 text-xs mt-1">Purchased in Kyoto, 2024</span>
                </cite>
            </section>
            </>
        )}

        {view === AppView.SEARCH_RESULTS && <SearchResultsPage />}
        {view === AppView.BUY && <ListingPage title="Properties for Sale" filterType="sale" />}
        {view === AppView.RENT && <ListingPage title="Exclusive Rentals" filterType="rent" />}
        {view === AppView.NEW_DEVELOPMENTS && <ListingPage title="New Developments" filterType="new" />}
        {view === AppView.JOURNAL && <JournalPage />}
        {view === AppView.CONTACT && <ContactPage />}

        {view === AppView.DETAILS && selectedProperty && (
            <main className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="relative h-[70vh] w-full">
                <img src={selectedProperty.imageUrl} alt={selectedProperty.title} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/30"></div>
                <button 
                    onClick={handleGoHome}
                    className="absolute top-24 left-6 md:left-12 text-white flex items-center gap-2 hover:text-luxe-sand transition-colors z-20 bg-black/20 px-4 py-2 rounded-full backdrop-blur-md"
                >
                    <ArrowLeft size={16} /> Back to Collection
                </button>

                <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-onyx to-transparent h-40"></div>
            </div>

            <div className="max-w-7xl mx-auto px-6 -mt-20 relative z-10 pb-20">
                <div className="flex flex-col lg:flex-row gap-16">
                    <div className="lg:w-2/3">
                    <div className="mb-8">
                        <span className="text-sky-teal uppercase tracking-widest text-sm font-medium">{selectedProperty.category}</span>
                        <h1 className="text-5xl md:text-6xl font-serif text-luxe-sand mt-2 mb-4">{selectedProperty.title}</h1>
                        <p className="text-xl text-gray-300 flex items-center gap-2">
                            <span className="text-white font-semibold">{selectedProperty.price}</span>
                            <span className="w-1 h-1 bg-gray-500 rounded-full"></span>
                            <span>{selectedProperty.location}</span>
                        </p>
                    </div>

                    <div className="grid grid-cols-3 gap-4 border-y border-white/10 py-8 mb-10">
                        <div className="text-center border-r border-white/10">
                            <span className="block text-3xl font-serif text-white">{selectedProperty.beds}</span>
                            <span className="text-xs text-gray-500 uppercase tracking-wider">Bedrooms</span>
                        </div>
                        <div className="text-center border-r border-white/10">
                            <span className="block text-3xl font-serif text-white">{selectedProperty.baths}</span>
                            <span className="text-xs text-gray-500 uppercase tracking-wider">Bathrooms</span>
                        </div>
                        <div className="text-center">
                            <span className="block text-3xl font-serif text-white">{selectedProperty.sqft.toLocaleString()}</span>
                            <span className="text-xs text-gray-500 uppercase tracking-wider">Sq Ft</span>
                        </div>
                    </div>

                    <h3 className="text-2xl font-serif text-white mb-6">The Narrative</h3>
                    <p className="text-gray-400 leading-relaxed text-lg mb-10 font-light">
                        {selectedProperty.description}
                    </p>

                    <h3 className="text-2xl font-serif text-white mb-6">Amenities</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mb-10">
                        {selectedProperty.features.map((feature, idx) => (
                            <div key={idx} className="flex items-center gap-3 text-gray-300">
                            <div className="p-1 rounded-full border border-sky-teal/30 text-sky-teal">
                                <Check size={10} />
                            </div>
                            <span>{feature}</span>
                            </div>
                        ))}
                    </div>
                    </div>

