import { MOCK_PROPERTIES } from "../constants";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const SYSTEM_INSTRUCTION = `
You are Nexora Realty's AI Concierge, a sophisticated, polite, and knowledgeable virtual assistant for ultra-luxury real estate.
Your tone is refined, professional, minimal, and helpful—like a concierge at a 7-star hotel.
You have access to the following exclusive property portfolio:
${JSON.stringify(MOCK_PROPERTIES.map(p => ({
  title: p.title,
  location: p.location,
  price: p.price,
  details: p.description,
  features: p.features.join(", ")
})))}

When users ask about properties, use this data. If they ask generally, provide high-end advice about luxury real estate trends (architecture, interior design, locations like Malibu, Como, NYC, Kyoto).
Keep answers concise and elegant. Do not use emojis excessively; maybe one gold star or sparkle if absolutely necessary, but prefer text.
If a user asks to book a viewing, politely suggest they use the "Book Viewing" button on the property page or contact the agent directly.
`;

export const generateAIResponse = async (history: { role: string; parts: { text: string }[] }[], message: string): Promise<string> => {
  try {
    const model = 'gemini-2.5-flash';
    const chat = ai.chats.create({
      model,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
      history: history,
    });

    const result = await chat.sendMessage({ message });
    return result.text || "I apologize, I am momentarily unable to access the archives. Please try again.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "I am currently experiencing a connection issue with the secure server. Please try again shortly.";
  }
};

